CREATE TYPE public.couple_role AS ENUM ('owner','partner');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.couple_role NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_couple_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) $$;
CREATE FUNCTION public.is_partner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='partner') $$;
REVOKE ALL ON FUNCTION public.is_couple_member(), public.is_partner() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_couple_member(), public.is_partner() TO authenticated;
CREATE POLICY member_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_path text NOT NULL UNIQUE, thumbnail_path text, media_type text NOT NULL CHECK(media_type IN ('photo','video')), original_filename text NOT NULL, file_size bigint NOT NULL CHECK(file_size>0), caption text, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((media_type='photo' AND file_size<=20971520) OR (media_type='video' AND file_size<=104857600)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.media TO authenticated;
GRANT ALL ON public.media TO service_role;
ALTER TABLE public.media ENABLE ROW LEVEL SECURITY;
CREATE POLICY view_memories ON public.media FOR SELECT TO authenticated USING(public.is_couple_member());
CREATE POLICY add_memories ON public.media FOR INSERT TO authenticated WITH CHECK(public.is_couple_member() AND created_by=auth.uid());
CREATE POLICY edit_memories ON public.media FOR UPDATE TO authenticated USING(public.is_couple_member()) WITH CHECK(public.is_couple_member());
CREATE POLICY delete_memories ON public.media FOR DELETE TO authenticated USING(public.is_couple_member());
CREATE INDEX media_newest ON public.media(created_at DESC);
CREATE FUNCTION public.protect_media_details() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN NEW.created_at:=OLD.created_at; NEW.created_by:=OLD.created_by; NEW.storage_path:=OLD.storage_path; NEW.media_type:=OLD.media_type; NEW.file_size:=OLD.file_size; NEW.original_filename:=OLD.original_filename; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER preserve_media BEFORE UPDATE ON public.media FOR EACH ROW EXECUTE FUNCTION public.protect_media_details();
CREATE TABLE public.date_requests (id uuid PRIMARY KEY, submitted_by uuid NOT NULL, requested_date date NOT NULL, time_category text NOT NULL CHECK(time_category IN ('Morning','Evening','Night')), requested_time text NOT NULL, activity text NOT NULL CHECK(activity IN ('Movie Date','Park Date','Mall Date','Mukbang Date','House Date','Other')), custom_activity text, destination text NOT NULL CHECK(length(trim(destination)) BETWEEN 1 AND 300), additional_request text CHECK(length(additional_request)<=2000), created_at timestamptz NOT NULL DEFAULT now(), email_status text NOT NULL DEFAULT 'pending' CHECK(email_status IN ('pending','sending','sent','failed')), email_claimed_at timestamptz, CHECK((time_category='Morning' AND requested_time IN ('08:00','09:00','10:00','11:00')) OR (time_category='Evening' AND requested_time IN ('16:00','17:00','18:00')) OR (time_category='Night' AND requested_time IN ('19:00','20:00','21:00'))), CHECK(activity<>'Other' OR length(trim(custom_activity)) BETWEEN 1 AND 300));
GRANT SELECT,INSERT ON public.date_requests TO authenticated;
GRANT ALL ON public.date_requests TO service_role;
ALTER TABLE public.date_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_request ON public.date_requests FOR SELECT TO authenticated USING(public.is_partner() AND submitted_by=auth.uid());
CREATE POLICY partner_request ON public.date_requests FOR INSERT TO authenticated WITH CHECK(public.is_partner() AND submitted_by=auth.uid() AND email_status='pending' AND email_claimed_at IS NULL);
CREATE FUNCTION public.validate_date_request() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.requested_date <= (now() AT TIME ZONE 'Asia/Jakarta')::date THEN RAISE EXCEPTION 'Choose tomorrow or a later date.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER future_dates BEFORE INSERT ON public.date_requests FOR EACH ROW EXECUTE FUNCTION public.validate_date_request();
CREATE POLICY private_media_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id IN ('photos','videos','thumbnails') AND public.is_couple_member());
CREATE POLICY private_media_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(public.is_couple_member() AND ((bucket_id IN ('photos','thumbnails') AND metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp','image/gif','image/heic','image/heif') AND (metadata->>'size')::bigint<=20971520) OR (bucket_id='videos' AND metadata->>'mimetype' IN ('video/mp4','video/webm','video/quicktime') AND (metadata->>'size')::bigint<=104857600)));
CREATE POLICY private_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id IN ('photos','videos','thumbnails') AND public.is_couple_member());